CREATE TRIGGER memory_recall_binding_delete AFTER DELETE ON memory_scope_bindings WHEN (OLD.id IN ('memory-owner-settings','memory-roster-policy') OR OLD.subject_type IN ('human-thread','human-binding','room','bot','person')) BEGIN
 UPDATE memory_recall_epoch SET epoch=epoch+1 WHERE id=1;
 DELETE FROM memory_recall_excluded;
 INSERT INTO memory_recall_excluded SELECT DISTINCT CAST(e.value AS TEXT) FROM memory_scope_bindings b,json_each(b.intent,'$.excludedThreadIds') e WHERE b.id='memory-owner-settings'; END

CREATE TRIGGER memory_recall_binding_insert AFTER INSERT ON memory_scope_bindings WHEN (NEW.id IN ('memory-owner-settings','memory-roster-policy') OR NEW.subject_type IN ('human-thread','human-binding','room','bot','person')) BEGIN
 UPDATE memory_recall_epoch SET epoch=epoch+1 WHERE id=1;
 DELETE FROM memory_recall_excluded;
 INSERT INTO memory_recall_excluded SELECT DISTINCT CAST(e.value AS TEXT) FROM memory_scope_bindings b,json_each(b.intent,'$.excludedThreadIds') e WHERE b.id='memory-owner-settings'; END

CREATE TRIGGER memory_recall_binding_update AFTER UPDATE ON memory_scope_bindings WHEN (OLD.id IN ('memory-owner-settings','memory-roster-policy') OR OLD.subject_type IN ('human-thread','human-binding','room','bot','person')) OR (NEW.id IN ('memory-owner-settings','memory-roster-policy') OR NEW.subject_type IN ('human-thread','human-binding','room','bot','person')) BEGIN
 UPDATE memory_recall_epoch SET epoch=epoch+1 WHERE id=1;
 DELETE FROM memory_recall_excluded;
 INSERT INTO memory_recall_excluded SELECT DISTINCT CAST(e.value AS TEXT) FROM memory_scope_bindings b,json_each(b.intent,'$.excludedThreadIds') e WHERE b.id='memory-owner-settings'; END

CREATE TRIGGER memory_recall_change_trim AFTER INSERT ON memory_recall_changes BEGIN
 UPDATE memory_recall_epoch SET projection_floor=max(projection_floor,NEW.sequence-1000000) WHERE id=1;
 DELETE FROM memory_recall_changes WHERE sequence=NEW.sequence-1000000; END

CREATE TRIGGER memory_recall_contains_storage_i BEFORE INSERT ON memory_recall_contains BEGIN
 SELECT CASE WHEN (SELECT bytes FROM memory_recall_storage WHERE id=1)+512>536870912 THEN RAISE(ABORT,'MEMORY_RECALL_STORAGE_LIMIT') END;
 UPDATE memory_recall_storage SET bytes=bytes+512 WHERE id=1; END

